            if (OwnerMatch.equalsIgnoreCase(firstName, existing.getFirstName())
                    && OwnerMatch.equalsIgnoreCase(lastName, existing.getLastName())) {
                count++;
            }
        }
        owner.setNamesakeCount(count);
