            String code = other.getCustomerCode();
            if (code != null) {
                existing.add(code);
            }
        }

        String code = base;
        for (int n = 2; existing.contains(code); n++) {
            code = base + "-" + n;
        }
        owner.setCustomerCode(code);
    }
}

